#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
using namespace std;

int N;
vector<string> A, B;
vector<vector<int>> dists;

struct Edge {
    int u, v, cap, w;
    Edge(int a, int b, int c, int d) : u(a), v(b), cap(c), w(d) {}
};

struct MCMF {
    int nodes;
    vector<int> d, f, p;
    vector<Edge> e;
    int flow, cost;

    void reset(int n) {
        nodes = n;
        d.assign(n, INT_MAX);
        f.assign(n, 0);
        p.assign(n, -1);
    }

    void connect(int a, int b, int c, int w) {
        e.emplace_back(a, b, c, w);
        e.emplace_back(b, a, 0, -w);
    }

    void find_path(int s, int t) {
        reset(nodes);
        f[s] = INT_MAX;
        d[s] = 0;
        queue<int> q;
        vector<bool> inq(nodes, false);
        q.push(s);
        inq[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;
            for (size_t i = 0; i < e.size(); ++i) {
                auto& ed = e[i];
                if (ed.cap > 0 && d[ed.v] > d[ed.u] + ed.w) {
                    d[ed.v] = d[ed.u] + ed.w;
                    f[ed.v] = min(f[ed.u], ed.cap);
                    p[ed.v] = i;
                    if (!inq[ed.v]) {
                        q.push(ed.v);
                        inq[ed.v] = true;
                    }
                }
            }
        }
    }

    void run(int s, int t) {
        if (s == t) {
            flow = INT_MAX;
            cost = 0;
            return;
        }
        flow = 0;
        cost = 0;
        while (true) {
            find_path(s, t);
            if (f[t] == 0) break;
            for (int cur = t; cur != s; cur = e[p[cur]].u) {
                int rev = p[cur] ^ 1;
                e[p[cur]].cap -= f[t];
                e[rev].cap += f[t];
                cost += e[p[cur]].w * f[t];
            }
            flow += f[t];
        }
    }
};

#define IN(x) (2 * (x))
#define OUT(x) (2 * (x) + 1)

MCMF solver;
int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, 1, 0, -1};

void bfs(int sr, int sc, vector<vector<int>>& dist) {
    dist.assign(N, vector<int>(N, -1));
    dist[sr][sc] = 0;
    queue<int> q;
    q.push(sr * N + sc);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int r = cur / N, c = cur % N;
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < 0 || nr >= N || nc < 0 || nc >= N || dist[nr][nc] != -1 || A[nr][nc] == 'Y') continue;
            if (isdigit(B[nr][nc]) && B[nr][nc] != '0' && (dist[r][c] + 1 <= dists[nr][nc] || dists[nr][nc] == -1)) {
                dist[nr][nc] = dist[r][c] + 1;
                if (dist[nr][nc] != dists[nr][nc]) q.push(nr * N + nc);
            } else if (dists[nr][nc] == -1 || dists[nr][nc] > dist[r][c] + 1) {
                dist[nr][nc] = dist[r][c] + 1;
                q.push(nr * N + nc);
            }
        }
    }
}

void init_all(vector<string>& m, vector<vector<vector<int>>>& all) {
    all.resize(N * N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(m[i][j]) && m[i][j] != '0')
                bfs(i, j, all[i * N + j]);
}

void add_link(int i1, int j1, int i2, int j2) {
    int u = i1 * N + j1;
    int v = i2 * N + j2 + N * N;
    solver.connect(OUT(u), IN(v), 1000000, 0);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.txt", "rt", stdin);
#endif
    int n, t;
    cin >> n >> t;
    N = n;
    vector<string> a(n), b(n);
    int si = -1, sj = -1;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') {
                si = i;
                sj = j;
            }
    }
    A = a;
    for (int i = 0; i < n; ++i) cin >> b[i];
    B = b;
    vector<vector<int>> temp;
    vector<vector<vector<int>>> all_dists;
    dists.assign(N, vector<int>(N, 1000000000));
    bfs(si, sj, temp);
    dists = temp;
    init_all(A, all_dists);
    solver.reset(4 * N * N + 2);
    int src = 4 * N * N, dst = src + 1;
    for (int i = 0; i < N * N; ++i) {
        solver.connect(src, IN(i), 1000000, 0);
        solver.connect(OUT(N * N + i), dst, 1000000, 0);
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (isdigit(A[i][j])) {
                int idx = i * N + j;
                solver.connect(IN(idx), OUT(idx), 0, A[i][j] - '0');
            }
            if (isdigit(B[i][j])) {
                int idx = i * N + j + N * N;
                solver.connect(IN(idx), OUT(idx), 0, B[i][j] - '0');
            }
        }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(B[i][j]) && B[i][j] != '0')
                for (int k = 0; k < (int)all_dists.size(); ++k)
                    if (!all_dists[k].empty()) {
                        int x = k / N, y = k % N;
                        if (all_dists[k][i][j] == -1 || all_dists[k][i][j] > t) continue;
                        add_link(x, y, i, j);
                    }
    solver.run(src, dst);
    cout << solver.flow << endl;
    return 0;
}
